-- Retire l'artisanat des Tarides. Les pièces et pierres que possèdent les personnages disparaissent ; les
-- consommables reprennent leur sort et leurs ventes d'origine.
USE acore_world;
DELETE FROM spell_group WHERE id IN (1127, 1128, 1129);
DELETE FROM spell_group_stack_rules WHERE group_id IN (1127, 1128, 1129);
DELETE FROM spell_dbc WHERE ID IN (101609, 101610, 101611);
UPDATE item_template i JOIN solazeroth_v3_t8_objets_origine o ON o.entry = i.entry SET i.spellid_1 = o.spellid_1, i.spelltrigger_1 = o.spelltrigger_1, i.spellcharges_1 = o.spellcharges_1, i.spellcooldown_1 = o.spellcooldown_1, i.spellcategory_1 = o.spellcategory_1, i.spellcategorycooldown_1 = o.spellcategorycooldown_1, i.RequiredLevel = o.RequiredLevel, i.RequiredSkill = o.RequiredSkill, i.RequiredSkillRank = o.RequiredSkillRank;
INSERT IGNORE INTO npc_vendor SELECT * FROM solazeroth_v3_t8_ventes_origine;
DROP TABLE IF EXISTS solazeroth_v3_t8_objets_origine, solazeroth_v3_t8_ventes_origine;
